svg.script:
(() => {
  const root = document.documentElement;
  const nodes = Array.from(root.querySelectorAll(".diagram-component"));
  const baseUrl = window.location.href.split("#")[0];
  let active = null;

  function applyFocus(requested, updateLocation = true) {
    const exists = nodes.some(node => node.dataset.component === requested);
    active = exists && active !== requested ? requested : null;
    root.classList.toggle("focus-active", Boolean(active));

    for (const node of nodes) {
      const focused = node.dataset.component === active;
      node.classList.toggle("focused", focused);
      node.setAttribute("aria-pressed", String(focused));
    }

    if (updateLocation) {
      try {
        history.replaceState(null, "", active ? `${baseUrl}#${active}` : baseUrl);
      } catch (_) {
        // Some embedded SVG viewers do not expose writable history.
      }
    }
  }

  for (const node of nodes) {
    node.setAttribute("aria-pressed", "false");
    node.addEventListener("click", event => {
      event.stopPropagation();
      applyFocus(node.dataset.component);
    });
    node.addEventListener("keydown", event => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        event.stopPropagation();
        applyFocus(node.dataset.component);
      }
    });
  }

  root.addEventListener("click", event => {
    if (!event.target.closest(".diagram-component") && active) applyFocus(null);
  });
  window.addEventListener("keydown", event => {
    if (event.key === "Escape" && active) applyFocus(null);
  });

  const initial = decodeURIComponent(window.location.hash.slice(1));
  if (initial) applyFocus(initial, false);
})();
